'use strict';
const fs=require('fs'),path=require('path');
const OUT=path.join(__dirname,'mega_bulk2.json');
const all=[];
function add(act,short,sec,title,desc,ch,cht,cat,...kw){
  all.push({act,act_short:short,section:String(sec),section_title:title,
    section_desc:desc,chapter:String(ch),chapter_title:cht,category:cat,
    keywords:kw.flat()});
}

// ── IPC Chapter 5 Abetment through Chapter 23 Attempt ────────────────────
const IPC2=[
["107","Abetment of a thing","A person abets the doing of a thing who instigates any person to do it; or engages with one or more persons in any conspiracy for doing it, if an act or illegal omission takes place in pursuance of that conspiracy; or intentionally aids, by any act or illegal omission, the doing of that thing. Abetment requires both act and intention.","5","Abetment","Criminal Law",["IPC S107 abetment instigation conspiracy aid illegal omission intention three modes"]],
["108","Abettor","A person abets an offence who abets either the commission of an offence, or the commission of an act which would be an offence, if committed by a person capable by law of committing an offence with the same intention or knowledge as that of the abettor.","5","Abetment","Criminal Law",["IPC S108 abettor commission offence intention knowledge capable law"]],
["109","Punishment of abetment if act abetted is committed","Whoever abets any offence shall, if the act abetted is committed in consequence of the abetment, and no express provision is made for punishment of such abetment, be punished with the punishment provided for the offence. Same punishment as for the principal offence.","5","Abetment","Criminal Law",["IPC S109 punishment abetment act committed consequence same punishment principal offence"]],
["110","Punishment of abetment if person abetted does act with different intention","Whoever abets the commission of an offence shall, if the person abetted does the act with a different intention or knowledge from that of the abettor, be punished with the punishment provided for the offence which would have been committed if the act had been done with the intention or knowledge of the abettor.","5","Abetment","Criminal Law",["IPC S110 abetment different intention knowledge punished same as abettor's intention"]],
["111","Liability of abettor when one act abetted and different act done","When an act is abetted and a different act is done, the abettor is liable for the act done, in the same manner and to the same extent as if he had directly abetted it. Provided the act done was a probable consequence of the abetment, and was done under the influence of the instigation.","5","Abetment","Criminal Law",["IPC S111 abettor different act done probable consequence instigation liable"]],
["112","Abettor when liable to cumulative punishment","If the act for which the abettor is liable under S.111 is committed in addition to the act abetted, and constitutes a distinct offence, the abettor is liable to punishment for each of the offences.","5","Abetment","Criminal Law",["IPC S112 abettor cumulative punishment each offence distinct additional"]],
["113","Liability of abettor for different effect","When an act is abetted with the intention on the part of the abettor of causing a particular effect, and an act for which the abettor is liable in consequence of the abetment, causes a different effect from that intended by the abettor, the abettor is liable for the effect caused — provided he knew that the act abetted was likely to cause that effect.","5","Abetment","Criminal Law",["IPC S113 abettor different effect knew likely caused intention"]],
["114","Abettor present when offence is committed","Whenever any person who if absent would be liable to be punished as an abettor, is present when the act or offence for which he would be punishable in consequence of the abetment is committed, he shall be deemed to have committed such act or offence.","5","Abetment","Criminal Law",["IPC S114 abettor present offence committed deemed committed same liability"]],
["115","Abetment of offence punishable with death or life imprisonment — offence not committed","Whoever abets the commission of an offence punishable with death or imprisonment for life, shall, if that offence be not committed in consequence of the abetment, and no express provision is made for the punishment of such abetment, be punished with imprisonment for a term which may extend to seven years.","5","Abetment","Criminal Law",["IPC S115 abetment death life imprisonment not committed seven years"]],
["116","Abetment of offence punishable with imprisonment — offence not committed","Whoever abets an offence punishable with imprisonment shall, if that offence be not committed in consequence of the abetment, and no express provision is made by this Code for the punishment of such abetment, be punished with imprisonment of any description provided for that offence for a term which may extend to one-fourth part of the longest term provided for that offence; or with such fine as is provided for that offence, or with both.","5","Abetment","Criminal Law",["IPC S116 abetment imprisonment not committed one-fourth longest term fine"]],
["117","Abetting commission of offence by the public","Whoever abets the commission of an offence by the public generally or by any number or class of persons exceeding ten, shall be punished with imprisonment of either description for a term which may extend to three years, or with fine, or with both.","5","Abetment","Criminal Law",["IPC S117 abetment public more than ten persons three years fine"]],
["118","Concealing design to commit offence punishable with death","Whoever, intending to facilitate or knowing it to be likely that he will thereby facilitate the commission of an offence punishable with death or imprisonment for life, voluntarily conceals, by any act or illegal omission, the existence of a design to commit such offence — if offence committed: seven years; if not committed: three years.","5","Abetment","Criminal Law",["IPC S118 concealing design death life imprisonment offence seven years three years"]],
["119","Public servant concealing design to commit offence","Whoever, being a public servant intending to facilitate or knowing it to be likely that he will thereby facilitate the commission of an offence which it is his duty as such public servant to prevent, voluntarily conceals, by any act or illegal omission, the existence of a design to commit such offence — punishable with half the punishment for that offence.","5","Abetment","Criminal Law",["IPC S119 public servant conceal design prevent offence half punishment duty"]],
["120","Concealing design to commit offence punishable with imprisonment","Whoever, intending to facilitate the commission of an offence punishable with imprisonment, voluntarily conceals the existence of a design to commit such offence — if offence committed: one-fourth term; if not committed: one-eighth.","5","Abetment","Criminal Law",["IPC S120 concealing design imprisonment one-fourth one-eighth voluntary"]],
["120A","Definition of criminal conspiracy","When two or more persons agree to do, or cause to be done, an illegal act, or an act which is not illegal by illegal means, such an agreement is designated a criminal conspiracy. No agreement except to commit an offence shall amount to criminal conspiracy unless some act besides the agreement is done by one or more parties to the agreement in pursuance thereof.","5","Criminal Conspiracy","Criminal Law",["IPC S120A criminal conspiracy two or more persons agree illegal act illegal means agreement overt act"]],
["120B","Punishment of criminal conspiracy","Whoever is a party to a criminal conspiracy to commit an offence punishable with death, imprisonment for life, or rigorous imprisonment for two years or more, shall, where no express provision is made, be punished in the same manner as if he had abetted such offence. Whoever is a party to any other criminal conspiracy shall be punished with imprisonment up to six months or fine or both.","5","Criminal Conspiracy","Criminal Law",["IPC S120B punishment criminal conspiracy death life two years same as abetment six months others fine"]],
["121","Waging war against Government of India","Whoever wages war against the Government of India, or attempts to wage such war, or abets the waging of such war, shall be punished with death, or imprisonment for life and shall also be liable to fine. This is the most serious political offence.","6","Offences Against State","Criminal Law",["IPC S121 waging war Government India death life imprisonment fine attempt abetment"]],
["124","Assaulting President, Governor etc. to compel exercise of lawful power","Whoever, with the intention of inducing or compelling the President of India or Governor of any State to exercise or refrain from exercising any of the lawful powers of such President or Governor, assaults or wrongfully restrains, or overawes by means of criminal force, or attempts so to do — shall be punished with imprisonment up to seven years.","6","Offences Against State","Criminal Law",["IPC S124 assault President Governor compel restrain overawe criminal force seven years"]],
["141","Unlawful assembly","An assembly of five or more persons is designated an unlawful assembly if the common object is to overawe by criminal force the Central or State Government; to resist the execution of any law or legal process; to commit any mischief or criminal trespass; by means of criminal force to take any property; by criminal force to compel any person to do what he is not legally bound to do.","8","Offences Against Public Tranquility","Criminal Law",["IPC S141 unlawful assembly five persons common object overawe resist mischief criminal force property compel"]],
["142","Being member of unlawful assembly","Whoever, being aware of facts which render any assembly an unlawful assembly, intentionally joins that assembly, or continues in it, is said to be a member of an unlawful assembly.","8","Offences Against Public Tranquility","Criminal Law",["IPC S142 member unlawful assembly aware facts intentionally joins continues"]],
["143","Punishment","Whoever is a member of an unlawful assembly, shall be punished with imprisonment of either description for a term which may extend to six months, or with fine, or with both.","8","Offences Against Public Tranquility","Criminal Law",["IPC S143 punishment unlawful assembly six months fine member"]],
["145","Joining or continuing in unlawful assembly knowing it has been commanded to disperse","Whoever joins or continues in an unlawful assembly, knowing that such unlawful assembly has been commanded in the manner prescribed by law to disperse, shall be punished with imprisonment of either description for a term which may extend to two years, or with fine, or with both.","8","Offences Against Public Tranquility","Criminal Law",["IPC S145 joining continuing unlawful assembly ordered disperse two years fine"]],
["147","Punishment for rioting","Whoever is guilty of rioting, shall be punished with imprisonment of either description for a term which may extend to two years, or with fine, or with both.","8","Offences Against Public Tranquility","Criminal Law",["IPC S147 rioting punishment two years fine"]],
["148","Rioting armed with deadly weapon","Whoever is guilty of rioting, being armed with a deadly weapon or with anything which, used as a weapon of offence, is likely to cause death, shall be punished with imprisonment of either description for a term which may extend to three years, or with fine, or with both.","8","Offences Against Public Tranquility","Criminal Law",["IPC S148 rioting armed deadly weapon three years fine"]],
["149","Every member of unlawful assembly guilty of offence committed in prosecution of common object","If an offence is committed by any member of an unlawful assembly in prosecution of the common object of that assembly, or such as the members of that assembly knew to be likely to be committed, every person who is a member of the same assembly, is guilty of that offence.","8","Offences Against Public Tranquility","Criminal Law",["IPC S149 common object unlawful assembly every member guilty prosecution knew likely"]],
["152","Assaulting or obstructing public servant when suppressing riot","Whoever assaults or threatens to assault, or obstructs or attempts to obstruct, any public servant in the discharge of his duty in endeavouring to disperse an unlawful assembly, or to suppress a riot, shall be punished with imprisonment up to three years, or with fine, or with both.","8","Offences Against Public Tranquility","Criminal Law",["IPC S152 assault obstruct public servant suppress riot disperse three years fine"]],
["153","Wantonly giving provocation to cause riot","Whoever malignantly or wantonly by doing anything illegal, gives provocation to any person intending or knowing it to be likely that such provocation will cause the offence of rioting to be committed, shall be punished accordingly — if riot committed: one year; if not: six months.","8","Offences Against Public Tranquility","Criminal Law",["IPC S153 provocation riot wantonly malignantly illegal one year six months"]],
["154","Owner of land on which unlawful assembly held","Whenever any unlawful assembly or riot takes place, the owner or occupier of the land upon which such assembly is held, shall be punishable with fine up to one thousand rupees if he or his agent, knowing of such offence being committed, does not give notice to the nearest police station.","8","Offences Against Public Tranquility","Criminal Law",["IPC S154 owner occupier land unlawful assembly riot fine one thousand police notice"]],
["159","Affray","When two or more persons, by fighting in a public place, disturb the public peace, they are said to commit an affray.","8","Offences Against Public Tranquility","Criminal Law",["IPC S159 affray fighting public place disturb peace two persons"]],
["160","Punishment for committing affray","Whoever commits an affray, shall be punished with imprisonment of either description for a term which may extend to one month, or with fine not exceeding one hundred rupees, or with both.","8","Offences Against Public Tranquility","Criminal Law",["IPC S160 punishment affray one month hundred rupees fine"]],
["166","Public servant disobeying law","Whoever, being a public servant, knowingly disobeys any direction of the law as to the way in which he is to conduct himself as such public servant, intending to cause, or knowing it to be likely that he will by such disobedience cause injury to any person, shall be punished with simple imprisonment up to one year, or fine, or both.","9","Offences by Public Servants","Criminal Law",["IPC S166 public servant disobeying law direction injury one year fine"]],
["167","Public servant framing incorrect document to cause injury","Whoever, being a public servant, and being charged with the preparation or translation of any document, frames or translates that document in a manner which he knows to be incorrect, intending to cause injury to any person, shall be punished with imprisonment up to three years, or fine, or both.","9","Offences by Public Servants","Criminal Law",["IPC S167 public servant framing incorrect document translation injury three years fine"]],
["168","Public servant unlawfully engaging in trade","Whoever, being a public servant, and being legally bound not to engage in trade, engages in trade, shall be punished with simple imprisonment up to one year, or with fine, or both.","9","Offences by Public Servants","Criminal Law",["IPC S168 public servant engaging trade prohibited one year fine"]],
["169","Public servant unlawfully buying property","Whoever, being a public servant, and being legally bound not to purchase or bid for certain property, purchases or bids for that property, shall be punished with simple imprisonment up to two years, or fine, or both; and the property shall be confiscated.","9","Offences by Public Servants","Criminal Law",["IPC S169 public servant buying property prohibited two years fine confiscated"]],
["170","Personating a public servant","Whoever pretends to hold any particular office as public servant, and in such assumed character does any act under colour of such office, shall be punished with imprisonment up to two years, or with fine, or both.","9","Offences by Public Servants","Criminal Law",["IPC S170 personating public servant pretends assumed character two years fine"]],
["171","Wearing garb of public servant","Whoever, not being a public servant, wears the garb of a public servant or carries a token used by that class of public servants, shall be punished with imprisonment up to three months, or fine up to two hundred rupees, or both.","9","Offences by Public Servants","Criminal Law",["IPC S171 wearing garb public servant token three months two hundred rupees"]],
["172","Absconding to avoid service of summons","Whoever absconds in order to avoid being served with a summons, notice or order proceeding from any public servant legally competent to issue such summons — shall be punished with simple imprisonment up to one month, or fine up to five hundred rupees, or both. If summons to attend court: six months, or fine up to one thousand, or both.","10","Contempt of Lawful Authority","Criminal Law",["IPC S172 absconding avoid summons public servant one month five hundred court six months"]],
["174","Non-attendance in obedience to an order from public servant","Whoever, being legally bound to attend at a certain time and place in obedience to a summons from a public servant, intentionally omits to attend at that place or time, shall be punished with simple imprisonment up to one month, or fine up to five hundred rupees, or both.","10","Contempt of Lawful Authority","Criminal Law",["IPC S174 non-attendance summons public servant one month five hundred intentionally omits"]],
["175","Omission to produce document to public servant","Whoever, being legally bound to produce a document to any public servant, intentionally omits so to produce it, shall be punished with simple imprisonment up to one month, or fine up to five hundred rupees, or both.","10","Contempt of Lawful Authority","Criminal Law",["IPC S175 omission produce document public servant one month five hundred"]],
["177","Furnishing false information","Whoever, being legally bound to furnish information on any subject to any public servant, furnishes as true information which he knows to be false, shall be punished with simple imprisonment up to six months, or fine up to one thousand rupees, or both.","10","Contempt of Lawful Authority","Criminal Law",["IPC S177 false information public servant six months one thousand legally bound"]],
["178","Refusing oath before public servant","Whoever refuses to bind himself by an oath when required to do so by a public servant legally competent to require that he shall so bind himself, shall be punished with simple imprisonment up to six months, or fine up to one thousand rupees, or both.","10","Contempt of Lawful Authority","Criminal Law",["IPC S178 refusing oath public servant six months one thousand"]],
["179","Refusing to answer public servant","Whoever, being legally bound to state the truth on any subject to any public servant, refuses to answer any question demanded of him touching that subject by such public servant, shall be punished with simple imprisonment up to six months, or fine up to one thousand rupees, or both.","10","Contempt of Lawful Authority","Criminal Law",["IPC S179 refusing answer question public servant six months one thousand"]],
["186","Obstructing public servant in discharge of public functions","Whoever voluntarily obstructs any public servant in the discharge of his public functions, shall be punished with imprisonment up to three months, or fine up to five hundred rupees, or both.","10","Contempt of Lawful Authority","Criminal Law",["IPC S186 obstruct public servant functions three months five hundred"]],
["188","Disobedience to order of public servant","Whoever, knowing that by an order made by a public servant he is directed to abstain from a certain act or to do a certain thing, disobeys such direction in disregard of its provisions — if causing obstruction or injury: simple imprisonment up to one month or fine up to two hundred rupees; if causing danger to human life, health or safety: six months or fine up to one thousand.","10","Contempt of Lawful Authority","Criminal Law",["IPC S188 disobedience order public servant one month two hundred danger six months one thousand"]],
["193","Punishment for false evidence","Whoever intentionally gives false evidence in any judicial proceeding, or fabricates false evidence for the purpose of being used in any judicial proceeding, shall be punished with imprisonment up to seven years; and whoever intentionally gives false evidence in any other case shall be punished with imprisonment up to three years.","11","False Evidence","Criminal Law",["IPC S193 false evidence judicial proceeding seven years fabricate other case three years"]],
["197","Issuing or signing false certificate","Whoever issues or signs any certificate required by law knowing that such certificate is false in any material point, shall be punished in the same manner as if he gave false evidence.","11","False Evidence","Criminal Law",["IPC S197 false certificate signs issues material point same as false evidence"]],
["201","Causing disappearance of evidence to screen offender","Whoever, knowing or having reason to believe that an offence has been committed, causes any evidence of the commission of that offence to disappear, with the intention of screening the offender from legal punishment, or gives false information respecting the offence — shall be punished with imprisonment extending to seven years (if offence punishable with death).","11","False Evidence","Criminal Law",["IPC S201 disappearance evidence screen offender seven years offence death punishment"]],
["202","Intentional omission to give information of offence","Whoever, knowing or having reason to believe that an offence has been committed, intentionally omits to give any information respecting that offence which he is legally bound to give, shall be punished with imprisonment up to six months, or fine, or both.","11","False Evidence","Criminal Law",["IPC S202 intentional omission information offence legally bound six months fine"]],
["203","Giving false information respecting offence","Whoever, knowing or having reason to believe that an offence has been committed, gives any information respecting that offence which he knows or believes to be false, shall be punished with imprisonment up to two years, or with fine, or with both.","11","False Evidence","Criminal Law",["IPC S203 false information offence two years fine"]],
["204","Destruction of document to prevent production as evidence","Whoever secretes or destroys any document or electronic record which he may be lawfully compelled to produce as evidence in court, or obliterates or renders illegible any part of it with the intention of preventing it from being produced or used, shall be punished with imprisonment up to two years, or fine, or both.","11","False Evidence","Criminal Law",["IPC S204 destroy document evidence court two years fine obliterates renders illegible prevent"]],
["211","False charge of offence with intent to injure","Whoever, with intent to cause injury to any person, institutes or causes to be instituted any criminal proceeding against that person, or falsely charges any person with having committed an offence, knowing that there is no just or lawful ground, shall be punished with imprisonment up to two years or fine or both; if charge of capital offence: seven years.","11","False Evidence","Criminal Law",["IPC S211 false charge intent injure criminal proceeding two years capital seven years"]],
["212","Harbouring offender","Whoever harbours or conceals a person whom he knows or has reason to believe to be the offender, with the intention of screening him from legal punishment — punishment equals up to one-fifth of the punishment for the offence (if punishable with death: five years; life: three years).","11","False Evidence","Criminal Law",["IPC S212 harbouring concealing offender screen punishment one-fifth death five years life three years"]],
["215","Taking gift to screen offender from punishment","Whoever takes or agrees to take any gratification, or restores or causes the restoration of any property, in consideration of screening any person from legal punishment, shall be punished — if offence punishable with death: seven years; if punishable with imprisonment for life: three years; others: two years.","11","False Evidence","Criminal Law",["IPC S215 taking gift screen offender punishment death seven years life three years two years gratification"]],
["217","Public servant disobeying law to save person from punishment","Whoever, being a public servant, knowingly disobeys any direction of the law as to the way in which he is to conduct himself, intending to save any person from legal punishment, or to subject him to a less punishment, shall be punished with imprisonment up to two years, or fine, or both.","11","False Evidence","Criminal Law",["IPC S217 public servant disobeying law save from punishment two years fine"]],
["218","Public servant framing incorrect record to save person","Whoever, being a public servant, and being charged with the preparation of any record, frames that record in a manner which he knows to be incorrect, with intent to cause, or knowing it to be likely that he will thereby cause, loss or injury to the public or to any person, or in order to save any person from legal punishment, shall be punished with imprisonment up to three years.","11","False Evidence","Criminal Law",["IPC S218 public servant framing incorrect record save punishment three years"]],
["220","Commitment for trial by person having authority who knows acting contrary to law","Whoever, being in any office which gives him legal authority to commit persons for trial, corruptly or maliciously commits any person for trial, knowing that in so doing he is acting contrary to law, shall be punished with imprisonment up to seven years, or with fine, or with both.","11","False Evidence","Criminal Law",["IPC S220 commitment trial authority contrary law maliciously corruptly seven years fine"]],
["224","Resistance or obstruction by a person to his lawful apprehension","Whoever intentionally offers any resistance or illegal obstruction to the lawful apprehension of himself for any offence with which he is charged, or escapes or attempts to escape from any custody in which he is lawfully detained, shall be punished with imprisonment up to two years, or fine, or both.","11","False Evidence","Criminal Law",["IPC S224 resistance obstruction lawful apprehension escape custody two years fine"]],
["225","Resistance or obstruction to lawful apprehension of another person","Whoever intentionally offers any resistance or illegal obstruction to the lawful apprehension of any other person for an offence, or rescues or attempts to rescue any other person from any custody in which that person is lawfully detained, shall be punished with imprisonment up to two years, or fine, or both.","11","False Evidence","Criminal Law",["IPC S225 resistance obstruction apprehension another rescue custody two years fine"]],
["228","Intentional insult or interruption to public servant sitting in judicial proceeding","Whoever intentionally offers any insult, or causes any interruption to any public servant, while such public servant is sitting in any stage of a judicial proceeding, shall be punished with simple imprisonment up to six months, or fine up to one thousand rupees, or both.","11","False Evidence","Criminal Law",["IPC S228 insult interruption public servant judicial proceeding six months one thousand"]],
["229","Personation of a juror or assessor","Whoever, by personation or otherwise, shall intentionally cause, or knowingly suffer himself to be empanelled as a juryman or assessor in any case in which he knows that he is not entitled by law to be so empanelled, shall be punished with imprisonment up to two years, or fine, or both.","11","False Evidence","Criminal Law",["IPC S229 personation juror assessor two years fine not entitled knowingly"]],
["231","Counterfeiting coin","Whoever counterfeits or knowingly performs any part of the process of counterfeiting coin, shall be punished with imprisonment up to seven years, and shall also be liable to fine.","12","Coin and Stamps","Criminal Law",["IPC S231 counterfeiting coin seven years fine process"]],
["232","Counterfeiting Indian coin","Whoever counterfeits, or knowingly performs any part of the process of counterfeiting Indian coin, shall be punished with imprisonment for life, or with imprisonment up to ten years, and shall also be liable to fine.","12","Coin and Stamps","Criminal Law",["IPC S232 counterfeiting Indian coin life imprisonment ten years fine"]],
["268","Public nuisance","A person is guilty of a public nuisance who does any act or is guilty of an illegal omission which causes any common injury, danger or annoyance to the public, or to the people who dwell or occupy property in the vicinity.","14","Public Health","Criminal Law",["IPC S268 public nuisance act omission common injury danger annoyance vicinity"]],
["272","Adulteration of food or drink","Whoever adulterates any article of food or drink, so as to make such article noxious as food or drink, intending to sell such article, shall be punished with imprisonment up to six months, or fine up to one thousand rupees, or both.","14","Public Health","Criminal Law",["IPC S272 adulteration food drink noxious sell six months one thousand"]],
["273","Sale of noxious food or drink","Whoever sells, or offers or exposes for sale, as food or drink, any article which has been rendered noxious, or is in a state unfit for food or drink, knowing that it is noxious, shall be punished with imprisonment up to six months, or fine up to one thousand rupees, or both.","14","Public Health","Criminal Law",["IPC S273 sale noxious food drink six months one thousand fine"]],
["277","Fouling water of public spring or reservoir","Whoever voluntarily corrupts or fouls the water of any public spring or reservoir, so as to render it less fit for the purpose for which it is ordinarily used, shall be punished with imprisonment up to three months, or fine up to five hundred rupees, or both.","14","Public Health","Criminal Law",["IPC S277 fouling water public spring reservoir three months five hundred"]],
["279","Rash driving or riding on public way","Whoever drives any vehicle, or rides, on any public way in a manner so rash or negligent as to endanger human life, or to be likely to cause hurt or injury, shall be punished with imprisonment up to six months, or fine up to one thousand rupees, or both.","14","Public Health","Criminal Law",["IPC S279 rash driving riding public way negligent endanger human life six months one thousand"]],
["295","Injuring or defiling place of worship with intent to insult the religion","Whoever destroys, damages or defiles any place of worship, or any object held sacred by any class of persons with the intention of insulting the religion of any class of persons, shall be punished with imprisonment up to two years, or fine, or both.","15","Offences Relating to Religion","Criminal Law",["IPC S295 injuring defiling place of worship insult religion two years fine destroy damage"]],
["296","Disturbing religious assembly","Whoever voluntarily causes disturbance to any assembly lawfully engaged in the performance of religious worship, shall be punished with imprisonment up to one year, or fine, or both.","15","Offences Relating to Religion","Criminal Law",["IPC S296 disturbing religious assembly worship one year fine"]],
["297","Trespassing on burial places","Whoever, with the intention of wounding the feelings of any person or of insulting the religion of any person, commits any trespass in any place of worship or on any place of sepulture, or offers any indignity to any human corpse, shall be punished with imprisonment up to one year, or fine, or both.","15","Offences Relating to Religion","Criminal Law",["IPC S297 trespassing burial places sepulture corpse indignity one year fine"]],
["298","Uttering words to wound religious feelings","Whoever, with the deliberate intention of wounding the religious feelings of any person, utters any word or makes any sound or makes any gesture or places any object in the sight of that person, shall be punished with imprisonment up to one year, or fine, or both.","15","Offences Relating to Religion","Criminal Law",["IPC S298 uttering words wound religious feelings one year fine deliberate gesture"]],
["304","Punishment for culpable homicide not amounting to murder","Whoever commits culpable homicide not amounting to murder shall be punished with imprisonment for life, or imprisonment up to ten years, and shall also be liable to fine, if the act by which the death is caused is done with the intention of causing death, or of causing such bodily injury as is likely to cause death. Part II: if no intention of causing death but knowledge of likelihood: imprisonment up to ten years or fine or both.","16","Offences Against Human Body","Criminal Law",["IPC S304 culpable homicide not murder life imprisonment ten years fine intention knowledge Part I Part II"]],
["306","Abetment of suicide","If any person commits suicide, whoever abets the commission of such suicide, shall be punished with imprisonment up to ten years, and shall also be liable to fine.","16","Offences Against Human Body","Criminal Law",["IPC S306 abetment suicide ten years fine commission"]],
["335","Voluntarily causing grievous hurt on provocation","Whoever voluntarily causes grievous hurt on grave and sudden provocation, if he neither intends nor knows himself to be likely to cause grievous hurt to any person other than the person who gave the provocation, shall be punished with imprisonment up to four years, or fine up to two thousand rupees, or both.","16","Hurt","Criminal Law",["IPC S335 grievous hurt provocation sudden grave four years two thousand"]],
["336","Act endangering life or personal safety","Whoever does any act so rashly or negligently as to endanger human life or the personal safety of others, shall be punished with imprisonment up to three months, or fine up to two hundred fifty rupees, or both.","16","Hurt","Criminal Law",["IPC S336 act endangering life personal safety rashly negligently three months two fifty"]],
["363","Punishment for kidnapping","Whoever kidnaps any person from India or from lawful guardianship, shall be punished with imprisonment up to seven years, and shall also be liable to fine.","16","Kidnapping","Criminal Law",["IPC S363 punishment kidnapping seven years fine India guardianship"]],
["364","Kidnapping or abducting in order to murder","Whoever kidnaps or abducts any person in order that such person may be murdered or may be so disposed of as to be put in danger of being murdered, shall be punished with imprisonment for life or rigorous imprisonment up to ten years, and shall also be liable to fine.","16","Kidnapping","Criminal Law",["IPC S364 kidnapping abducting murder life imprisonment ten years fine"]],
["365","Kidnapping with intent to secretly confine","Whoever kidnaps or abducts any person with intent to cause that person to be secretly and wrongfully confined, shall be punished with imprisonment up to seven years, and shall also be liable to fine.","16","Kidnapping","Criminal Law",["IPC S365 kidnapping wrongful confinement secret seven years fine"]],
["366","Kidnapping to compel marriage","Whoever kidnaps or abducts any woman with intent that she may be compelled, or knowing it to be likely that she will be compelled, to marry any person against her will, or in order that she may be forced or seduced to illicit intercourse, shall be punished with imprisonment up to ten years, and shall also be liable to fine.","16","Kidnapping","Criminal Law",["IPC S366 kidnapping woman marriage against will illicit intercourse ten years fine"]],
["373","Buying minor for purposes of prostitution","Whoever buys, hires or otherwise obtains possession of any person under the age of eighteen years with intent that such person shall at any age be employed or used for the purpose of prostitution or illicit intercourse, shall be punished with imprisonment up to ten years, and shall also be liable to fine.","16","Slavery","Criminal Law",["IPC S373 buying minor prostitution illicit intercourse ten years fine eighteen years"]],
["374","Unlawful compulsory labour","Whoever unlawfully compels any person to labour against the will of that person, shall be punished with imprisonment up to one year, or with fine, or with both.","16","Slavery","Criminal Law",["IPC S374 compulsory labour against will one year fine"]],
["379","Punishment for theft","Whoever commits theft shall be punished with imprisonment up to three years, or with fine, or with both.","17","Theft","Criminal Law",["IPC S379 punishment theft three years fine"]],
["380","Theft in dwelling house","Whoever commits theft in any building, tent or vessel, which is used as a human dwelling, or used for the custody of property, shall be punished with imprisonment up to seven years, and shall also be liable to fine.","17","Theft","Criminal Law",["IPC S380 theft dwelling house building tent vessel seven years fine"]],
["382","Theft after preparation for hurt","Whoever commits theft, having made preparation for causing death or hurt or restraint in order to committing such theft, or in order to effecting his escape, shall be punished with rigorous imprisonment up to ten years, and shall also be liable to fine.","17","Theft","Criminal Law",["IPC S382 theft preparation hurt death restraint escape ten years fine rigorous"]],
["392","Punishment for robbery","Whoever commits robbery shall be punished with rigorous imprisonment up to ten years, and shall also be liable to fine; and if robbery be committed on the highway between sunset and sunrise, the imprisonment may be extended to fourteen years.","17","Robbery","Criminal Law",["IPC S392 robbery ten years fine highway sunset sunrise fourteen years"]],
["395","Punishment for dacoity","Whoever commits dacoity shall be punished with imprisonment for life, or with rigorous imprisonment up to ten years, and shall also be liable to fine.","17","Dacoity","Criminal Law",["IPC S395 dacoity punishment life imprisonment ten years fine"]],
["417","Punishment for cheating","Whoever cheats shall be punished with imprisonment up to one year, or with fine, or with both.","17","Cheating","Criminal Law",["IPC S417 punishment cheating one year fine"]],
["420","Cheating and dishonestly inducing delivery of property","Whoever cheats and thereby dishonestly induces the person deceived to deliver any property to any person, or to make, alter or destroy any valuable security, shall be punished with imprisonment up to seven years, and shall also be liable to fine.","17","Cheating","Criminal Law",["IPC S420 cheating dishonest induce delivery property seven years fine valuable security"]],
["447","Punishment for criminal trespass","Whoever commits criminal trespass shall be punished with imprisonment up to three months, or fine up to five hundred rupees, or both.","17","Trespass","Criminal Law",["IPC S447 punishment criminal trespass three months five hundred"]],
["499","Defamation","Whoever by words either spoken or intended to be read, or by signs or by visible representations, makes or publishes any imputation concerning any person intending to harm, or knowing or having reason to believe that such imputation will harm, the reputation of such person, is said to defame that person. Ten exceptions including truth, public good, fair comment, report of judicial proceedings.","21","Defamation","Criminal Law",["IPC S499 defamation words signs visible representations imputation reputation harm ten exceptions truth public good fair comment"]],
["500","Punishment for defamation","Whoever defames another shall be punished with simple imprisonment up to two years, or with fine, or with both.","21","Defamation","Criminal Law",["IPC S500 defamation punishment two years simple imprisonment fine"]],
["503","Criminal intimidation","Whoever threatens another with any injury to his person, reputation or property, or to the person or reputation of any one in whom that person is interested, with intent to cause alarm, or to cause that person to do any act which he is not legally bound to do, or to omit to do any act which that person is legally entitled to do, commits criminal intimidation.","22","Criminal Intimidation","Criminal Law",["IPC S503 criminal intimidation threat injury person reputation property alarm compel omit"]],
["506","Punishment for criminal intimidation","Whoever commits the offence of criminal intimidation shall be punished with imprisonment up to two years, or with fine, or with both; and if the threat be to cause death or grievous hurt, or to cause the destruction of any property by fire, or to cause an offence punishable with death or imprisonment for life, imprisonment up to seven years, or fine, or both.","22","Criminal Intimidation","Criminal Law",["IPC S506 criminal intimidation punishment two years seven years death grievous hurt fire fine"]],
["509","Word, gesture or act intended to insult modesty of woman","Whoever, intending to insult the modesty of any woman, utters any word, makes any sound or gesture, or exhibits any object, intending that such word or sound shall be heard, or that such gesture or object shall be seen by such woman, or intrudes upon the privacy of such woman, shall be punished with simple imprisonment up to three years, and also with fine.","22","Criminal Intimidation","Criminal Law",["IPC S509 insult modesty woman word gesture sound three years fine privacy intrude"]],
["510","Misconduct in public by a drunken person","Whoever, in a state of intoxication, appears in any public place, or in any place which it is a trespass in him to enter, and there conducts himself in such a manner as to cause annoyance to any person, shall be punished with simple imprisonment up to twenty-four hours, or with fine up to ten rupees, or with both.","22","Criminal Intimidation","Criminal Law",["IPC S510 drunken misconduct public place intoxication annoyance twenty-four hours ten rupees"]],
["511","Punishment for attempting to commit offences","Whoever attempts to commit an offence punishable by this Code with imprisonment, and in such attempt does any act towards the commission of the offence, shall, where no express provision is made for the punishment of such attempt, be punished with imprisonment of any description provided for the offence, for a term which may extend to one-half of the imprisonment for life or the longest term provided.","23","Attempts","Criminal Law",["IPC S511 attempt commit offence one-half longest term imprisonment no express provision"]],
];
IPC2.forEach(([sec,title,desc,ch,cht,cat,kw])=>add("Indian Penal Code, 1860","IPC",sec,title,desc,ch,cht,cat,...[kw]));

// ── CrPC Sections 61 to 530 (comprehensive coverage) ─────────────────────
const CRPC2=[
["61","Form of summons","Every summons issued by a court under this Code shall be in writing, in duplicate, signed by the presiding officer of such court or by such other officer as the High Court may, from time to time, by rule direct, and shall bear the seal of the court.","5","Summons","Criminal Procedure",["CrPC S61 summons form writing duplicate signed presiding officer High Court rule seal"]],
["62","Summons — how served","Every summons shall be served by a police officer, or subject to such rules as the State Government may make in this behalf, by an officer of the court issuing it or other public servant. The summons shall, if practicable, be served personally on the person summoned, by delivering or tendering to him one of the duplicates of the summons.","5","Summons","Criminal Procedure",["CrPC S62 summons served police officer court officer public servant personally delivering duplicate"]],
["63","Service of summons on corporate bodies and societies","Service of a summons on a corporation may be effected by serving it on the secretary, local manager or other principal officer of the corporation, or by letter sent by registered post, addressed to the chief officer of the corporation in India.","5","Summons","Criminal Procedure",["CrPC S63 summons corporation society secretary manager registered post chief officer India"]],
["69","Service when persons summoned cannot be found","Where the person summoned cannot by the exercise of due diligence be found, the summons may be served by leaving one of the duplicates for him with some adult male member of his family residing with him, and the other duplicate shall be attached to some conspicuous part of the house or homestead in which he ordinarily resides.","5","Summons","Criminal Procedure",["CrPC S69 summons not found due diligence adult male family member attach house homestead"]],
["70","Warrant — Form","Every warrant of arrest issued by a court under this Code shall be in writing, signed by the presiding officer of such court and shall bear the seal of the court. Every warrant shall remain in force until it is cancelled by the court which issued it, or until it is executed.","6","Warrants","Criminal Procedure",["CrPC S70 warrant arrest form writing signed presiding officer seal remains force until cancelled executed"]],
["71","Power to direct security to be taken","Any court issuing a warrant for the arrest of any person may in its discretion direct by endorsement on the warrant that, if such person executes a bond with sufficient sureties for his attendance before the court at a specified time and thereafter until otherwise directed by the court, the officer to whom the warrant is directed shall take such security and shall release such person from custody.","6","Warrants","Criminal Procedure",["CrPC S71 warrant security bond sureties bail court endorsement attendance release custody"]],
["72","Warrants to whom directed","A warrant of arrest shall ordinarily be directed to one or more police officers; but the court issuing such a warrant may, if its immediate execution is necessary and no police officer is immediately available, direct it to any other person or persons, and such person or persons shall execute the same.","6","Warrants","Criminal Procedure",["CrPC S72 warrant directed police officer immediate execution necessary any other person"]],
["73","Warrant may be directed to any person","The Chief Judicial Magistrate or a Magistrate of the first class may direct a warrant to any person within his local jurisdiction for the arrest of any escaped convict, proclaimed offender or of any person who is accused of a non-bailable offence and is evading arrest.","6","Warrants","Criminal Procedure",["CrPC S73 warrant any person CJM first class escaped convict proclaimed offender non-bailable evading"]],
["74","Warrant directed to police officer","A warrant directed to any police officer may also be executed by any other police officer whose name is endorsed upon the warrant by the officer to whom it is directed or endorsed.","6","Warrants","Criminal Procedure",["CrPC S74 warrant police officer executed another officer endorsed name"]],
["75","Notification of substance of warrant","The police officer or other person executing a warrant of arrest shall notify the substance thereof to the person to be arrested, and, if so required, shall show him the warrant.","6","Warrants","Criminal Procedure",["CrPC S75 notify substance warrant person arrested show if required"]],
["76","Person arrested to be brought before court without delay","The police officer or other person executing a warrant of arrest shall, subject to the provisions of section 71 as to security, without unnecessary delay bring the person arrested before the court before which he is required by law to produce such person.","6","Warrants","Criminal Procedure",["CrPC S76 brought court without delay arrest warrant section 71 security produce"]],
["77","Where warrant may be executed","A warrant of arrest may be executed at any place in India.","6","Warrants","Criminal Procedure",["CrPC S77 warrant executed any place India"]],
["78","Warrant forwarded for execution outside jurisdiction","When a warrant is to be executed beyond the local jurisdiction of the court issuing it, such court may, instead of directing the warrant to a police officer within its jurisdiction, forward it by post or otherwise to any Executive Magistrate or District Superintendent of Police or Commissioner of Police within the local limits of whose jurisdiction it is to be executed.","6","Warrants","Criminal Procedure",["CrPC S78 warrant forwarded outside jurisdiction Executive Magistrate DSP Commissioner post"]],
["79","Warrant directed to police officer for execution outside jurisdiction","When a warrant directed to a police officer is to be executed beyond the local jurisdiction of the court issuing the same, he shall ordinarily take it for endorsement either to an Executive Magistrate or to a police officer not below the rank of an officer in charge of a police station, within the local limits of whose jurisdiction the warrant is to be executed.","6","Warrants","Criminal Procedure",["CrPC S79 warrant police officer outside jurisdiction endorsement Executive Magistrate police station rank"]],
["82","Proclamation for person absconding","If any court has reason to believe that any person against whom a warrant has been issued by it has absconded or is concealing himself so that such warrant cannot be executed, such court may publish a written proclamation requiring him to appear at a specified place and at a specified time not less than thirty days from the date of publishing such proclamation.","7","Proclamation","Criminal Procedure",["CrPC S82 proclamation absconding concealing warrant thirty days specified place time publish"]],
["83","Attachment of property of person absconding","The court issuing a proclamation under section 82 may, for reasons to be recorded in writing, at any time after the issue of the proclamation, order the attachment of any property, movable or immovable, or both, belonging to the proclaimed person.","7","Proclamation","Criminal Procedure",["CrPC S83 attachment property proclaimed person movable immovable writing reasons court"]],
["84","Claims and objections to attachment","If any claim is preferred to, or objection made to the attachment of, any property attached under section 83, within thirty days from the date of such attachment, by any person other than the proclaimed person, on the ground that the claimant or objector has an interest in such property, and that such interest is not liable to attachment, the claim or objection shall be inquired into.","7","Proclamation","Criminal Procedure",["CrPC S84 claim objection attachment thirty days proclaimed person interest not liable inquiry"]],
["87","Issue of warrant in lieu of or in addition to summons","A court may, in any case in which it is empowered by this Code to issue a summons for the appearance of any person, issue, after recording its reasons in writing, a warrant for his arrest, if either before the issue of such summons or after the issue of the same but before the time fixed for his appearance, the court sees reason to believe that he has absconded or will not obey the summons.","7","Summons and Warrants","Criminal Procedure",["CrPC S87 warrant in lieu summons absconded not obey reasons writing court issue"]],
["88","Power to take bond for appearance","When any person for whose appearance or arrest the officer presiding in any court is empowered to issue a summons or warrant, is present in such court, such officer may require such person to execute a bond, with or without sureties, for his appearance in such court.","7","Summons and Warrants","Criminal Procedure",["CrPC S88 bond appearance person present court sureties execute require officer"]],
["89","Arrest on breach of bond for appearance","When any person who is bound by any bond taken under this Code to appear before a court, does not appear, the officer presiding in such court may issue a warrant directing that such person be arrested and produced before him.","7","Summons and Warrants","Criminal Procedure",["CrPC S89 arrest breach bond appearance warrant court officer presiding produce"]],
["91","Summons to produce document or thing","Whenever any court or any officer in charge of a police station considers that the production of any document or other thing is necessary or desirable for the purposes of any investigation, inquiry, trial or other proceeding under this Code, such court or officer may issue a summons, or a written order, as the case may be, to the person in whose possession or power such document or thing is believed to be.","7","Summons","Criminal Procedure",["CrPC S91 summons produce document thing court police investigation inquiry trial possession power"]],
["92","Procedure as to letters and telegrams","Where any document, parcel or thing in the custody of a postal or telegraph authority is, in the opinion of the District Magistrate, Chief Judicial Magistrate, or Court of Session or High Court, wanted for the purpose of any investigation, inquiry, trial or other proceeding under this Code, such Magistrate or Court may require the postal or telegraph authority to deliver such document, parcel or thing to such person as the Magistrate or Court directs.","7","Summons","Criminal Procedure",["CrPC S92 letters telegrams postal telegraph custody investigation inquiry trial High Court Magistrate"]],
["93","When search warrant may be issued","Where any court has reason to believe that a person to whom a summons or order under section 91 or a requisition under section 92 has been, or might be, addressed, will not or would not produce the document or thing as required by such summons or requisition, or such document or thing is not known to the court to be in the possession of any person, or that the purposes of any inquiry, trial or other proceeding under this Code will be served by a general search or inspection, it may issue a search warrant.","7","Search Warrants","Criminal Procedure",["CrPC S93 search warrant not produce document general search inspection inquiry trial court reason"]],
["94","Search of place suspected to contain stolen property etc.","If a District Magistrate, Sub-divisional Magistrate or Magistrate of the first class, upon information and after such inquiry as he thinks necessary, has reason to believe that any place is used for the deposit or sale of stolen property, or for the deposit, sale or production of any obscene object, or for the commission of any offence, he may by warrant authorise any police officer to enter and search such place.","7","Search Warrants","Criminal Procedure",["CrPC S94 search stolen property obscene deposit sale commission offence Magistrate warrant police"]],
["97","Search for persons wrongfully confined","If any District Magistrate, Sub-divisional Magistrate or Magistrate of the first class has reason to believe that any person is confined under such circumstances that the confinement amounts to an offence, he may issue a search warrant, and the person to whom such warrant is directed may search for the person so confined; and such search shall be made in accordance herewith.","7","Search Warrants","Criminal Procedure",["CrPC S97 search persons wrongfully confined offence warrant Magistrate directed search person"]],
["100","Persons in charge of closed place to allow search","Whenever any place liable to search or inspection under this Chapter is closed, any person residing in, or being in charge of, such place, shall, on demand of the officer or other person executing the warrant, and on production of the warrant, allow him free ingress thereto, and afford all reasonable facilities for a search therein.","7","Search Warrants","Criminal Procedure",["CrPC S100 closed place search warrant ingress facilities demand officer produce allow resident"]],
["101","Search in presence of witnesses","Before making a search under this Chapter, the officer or other person about to make it shall call upon two or more independent and respectable inhabitants of the locality in which the place to be searched is situate or of any other locality if no such inhabitant of the said locality is available or is willing to be a witness to the search.","7","Search Warrants","Criminal Procedure",["CrPC S101 search witnesses two respectable inhabitants locality independent willing panchnama"]],
["102","Power of police officer to seize certain property","Any police officer may seize any property which may be alleged or suspected to have been stolen, or which may be found under circumstances which create suspicion of the commission of any offence.","7","Search Warrants","Criminal Procedure",["CrPC S102 police seize property stolen circumstances suspicion commission offence"]],
["103","Magistrate may direct search in his presence","Any Magistrate may direct a search to be made in his presence of any place for the search of which he is competent to issue a search warrant.","7","Search Warrants","Criminal Procedure",["CrPC S103 Magistrate search presence competent warrant direct"]],
["107","Security for keeping the peace in other cases","Whenever any Executive Magistrate receives information that any person is likely to commit a breach of the peace or disturb the public tranquillity or to do any wrongful act that may probably occasion a breach of the peace or disturb the public tranquillity, he may require such person to show cause why he should not be ordered to execute a bond with or without sureties for keeping the peace.","8","Security for Peace","Criminal Procedure",["CrPC S107 security keeping peace breach disturbance Executive Magistrate show cause bond sureties wrongful act"]],
["108","Security for good behaviour from persons disseminating seditious matter","Whenever any Executive Magistrate receives information that there is within his local jurisdiction any person who, within or without such jurisdiction, disseminates or attempts to disseminate, or abets the dissemination of any matter concerning which it is an offence to disseminate, he may require such person to show cause.","8","Security for Behaviour","Criminal Procedure",["CrPC S108 security good behaviour seditious matter disseminate abets Executive Magistrate show cause"]],
["109","Security for good behaviour from suspected persons","Whenever any Executive Magistrate receives information that there is within his local jurisdiction a person taking precautions to conceal his presence and that there is reason to believe that he is doing so with a view to committing a cognizable offence, the Magistrate may require such person to show cause.","8","Security for Behaviour","Criminal Procedure",["CrPC S109 security suspected person conceal presence cognizable offence Executive Magistrate show cause"]],
["110","Security for good behaviour from habitual offenders","Whenever any Executive Magistrate receives information that there is within his local jurisdiction a person who is a habitual offender against any law in force, or who by the commission of an offence against property, has shown that he is dangerous to property, he may require such person to show cause.","8","Security for Behaviour","Criminal Procedure",["CrPC S110 habitual offender security property dangerous Executive Magistrate show cause"]],
["111","Order to be made when Magistrate acting under section 107 or 110","When a Magistrate acting under section 107 or section 110, deems it necessary to require any person to show cause under such section, he shall make an order in writing, setting forth the substance of the information received, the amount of the bond to be executed, the term for which it is to be in force, and the number, character and class of sureties.","8","Security for Behaviour","Criminal Procedure",["CrPC S111 order writing substance information bond term sureties number character class Magistrate S107 S110"]],
["125","Order for maintenance of wives, children and parents","If any person having sufficient means neglects or refuses to maintain his wife, his legitimate or illegitimate minor child unable to maintain himself, or his legitimate or illegitimate child (not being a married daughter) who has attained majority and unable to maintain itself due to physical or mental abnormality, or his father or mother unable to maintain themselves, a Magistrate of the first class may order monthly allowance.","9","Maintenance","Criminal Procedure",["CrPC S125 maintenance wife children parents Magistrate first class monthly allowance neglects refuses means sufficient"]],
["126","Procedure for maintenance","Proceedings under section 125 may be taken against any person in any district where he resides or his wife resides or where he last resided with his wife or the mother of the illegitimate child, or where he is.","9","Maintenance","Criminal Procedure",["CrPC S126 procedure maintenance district resides wife last resided mother illegitimate child"]],
["127","Alteration in allowance","On proof of a change in the circumstances of any person receiving, under section 125, a monthly allowance, or ordered under the same section to pay a monthly allowance to his wife, child, father or mother, as the case may be, the Magistrate may make such alteration in the allowance as he thinks fit.","9","Maintenance","Criminal Procedure",["CrPC S127 alteration allowance change circumstances Magistrate monthly maintenance wife child father mother"]],
["128","Enforcement of order of maintenance","A copy of the order of maintenance shall be given without payment to the person in whose favour it is made, or to his guardian, if any, or to the person to whom the allowance is to be paid; and such order may be enforced by any Magistrate in any place where the person against whom it is made may be, on such Magistrate being satisfied as to the identity of the parties.","9","Maintenance","Criminal Procedure",["CrPC S128 enforcement order maintenance copy without payment guardian Magistrate identity parties enforce"]],
["129","Dispersal of assembly by use of civil force","Any Executive Magistrate or officer in charge of a police station may command any unlawful assembly, or any assembly of five or more persons likely to cause a disturbance of the public peace, to disperse; and it shall thereupon be the duty of the members of such assembly to disperse accordingly.","10","Public Order","Criminal Procedure",["CrPC S129 dispersal assembly civil force Executive Magistrate five persons unlawful public peace"]],
["130","Use of civil force to disperse assembly","If, upon being so commanded, any such assembly does not disperse, or if, without being so commanded, it conducts itself in such a manner as to show a determination not to disperse, any Executive Magistrate or officer in charge of a police station may proceed to disperse such assembly by force.","10","Public Order","Criminal Procedure",["CrPC S130 use civil force disperse assembly determination not disperse Executive Magistrate police station"]],
["132","Protection against prosecution for acts done under section 129, 130 and 131","No prosecution against any person for any act purporting to be done under section 129, section 130 or section 131 shall be instituted in any Criminal Court except with the sanction of the Central Government.","10","Public Order","Criminal Procedure",["CrPC S132 protection prosecution sanction Central Government sections 129 130 131 dispersal assembly"]],
["133","Conditional order for removal of nuisance","Whenever a District Magistrate or a Sub-divisional Magistrate or any other Executive Magistrate specially empowered in this behalf, on receiving the report of a police officer or other information and on taking such evidence as he thinks fit, considers that any unlawful obstruction or nuisance should be removed from any public place or from any way, river or channel which is or may be lawfully used by the public, he may make a conditional order.","10","Public Order","Criminal Procedure",["CrPC S133 conditional order nuisance removal public place way river channel Magistrate police report evidence"]],
["144","Power to issue order in urgent cases of nuisance or apprehended danger","In cases where, in the opinion of a District Magistrate, a Sub-divisional Magistrate or any other Executive Magistrate specially empowered by the State Government in this behalf, there is sufficient ground for proceeding under this section and immediate prevention or speedy remedy is desirable, such Magistrate may, by a written order stating the material facts of the case, direct any person to abstain from a certain act or to take certain order with certain property in his possession or under his management.","10","Public Order","Criminal Procedure",["CrPC S144 urgent order nuisance apprehended danger Executive Magistrate written order abstain property two months prohibitory order"]],
["145","Procedure where dispute concerning land or water is likely to cause breach of peace","Whenever an Executive Magistrate is satisfied from a police report or other information that a dispute likely to cause a breach of the peace exists concerning any land or water or the boundaries thereof, and that such dispute is likely to cause a breach of the peace, he shall make an order in writing, stating the grounds of his being so satisfied.","10","Disputes","Criminal Procedure",["CrPC S145 dispute land water boundary breach peace Executive Magistrate police report written order possession determine"]],
["154","Information in cognizable cases — FIR requirements","Every information relating to the commission of a cognizable offence, if given orally to an officer in charge of a police station, shall be reduced to writing by him or under his direction, and be read over to the informant; and every such information shall be signed by the person giving it. A copy of the information as recorded shall be given forthwith, free of cost, to the informant.","12","FIR","Criminal Procedure",["CrPC S154 FIR cognizable information oral reduced writing signed informant copy free forthwith police station"]],
["155","Information as to non-cognizable cases and investigation of such cases","When information is given to an officer in charge of a police station of the commission of a non-cognizable offence, he shall enter or cause to be entered the substance of such information in a book to be kept by such officer in such form as the State Government may prescribe in this behalf, and refer the informant to the Magistrate.","12","Investigation","Criminal Procedure",["CrPC S155 non-cognizable information book State Government prescribed form refer Magistrate"]],
["157","Procedure for investigation","If from information received or otherwise, an officer in charge of a police station has reason to suspect the commission of an offence which he is empowered under section 156 to investigate, he shall forthwith send a report of the same to a Magistrate empowered to take cognizance of such offence upon a police report and shall proceed in person, or shall depute one of his subordinate officers to proceed, to the spot.","12","Investigation","Criminal Procedure",["CrPC S157 procedure investigation police station suspect report Magistrate forthwith spot subordinate"]],
["159","Power to hold investigation or preliminary inquiry","Such Magistrate may, whether the case is one in which the Magistrate has original jurisdiction or not, direct an investigation, or, if he thinks fit, at once proceed, or depute any Magistrate subordinate to him to proceed, to hold a preliminary inquiry into, or otherwise to dispose of, the case in the manner provided in this Code.","12","Investigation","Criminal Procedure",["CrPC S159 Magistrate hold investigation preliminary inquiry original jurisdiction depute subordinate dispose"]],
["160","Police officer's power to require attendance of witnesses","Any police officer making an investigation under this Chapter may, by order in writing, require the attendance before himself of any person being within the limits of his own or any adjoining station who, from the information given or otherwise, appears to be acquainted with the facts and circumstances of the case.","12","Investigation","Criminal Procedure",["CrPC S160 police officer require attendance witness writing acquainted facts circumstances investigation limits station"]],
["163","No inducement to be offered","No police officer or other person in authority shall offer or make, or cause to be offered or made, any such inducement, threat or promise as is mentioned in section 24 of the Indian Evidence Act, 1872, to any person for the purpose of causing him to make any statement with regard to the subject-matter of any proceeding touching the offence under investigation.","12","Investigation","Criminal Procedure",["CrPC S163 no inducement threat promise IEA S24 police authority statement subject matter investigation"]],
["164","Recording of confessions and statements","Any Metropolitan Magistrate or Judicial Magistrate may, whether or not he has jurisdiction in the case, record any confession or statement made to him in the course of an investigation under this Chapter. Before recording any such confession, the Magistrate shall explain to the person making it that he is not bound to make a confession.","12","Investigation","Criminal Procedure",["CrPC S164 recording confession statement Metropolitan Judicial Magistrate investigation explain not bound warning"]],
["165","Search by police officer","A police officer making an investigation under this Chapter may, within the limits of the police station of which he is in charge, and when authorised by a Magistrate of the first class having jurisdiction over the area to be searched or if he has reasonable grounds, search any place and seize anything found therein.","12","Investigation","Criminal Procedure",["CrPC S165 search police officer investigation station Magistrate first class authorised reasonable grounds seize"]],
["166","When officer in charge of police station may require another to issue search warrant","An officer in charge of a police station may apply to any Magistrate within the local limits of whose jurisdiction a place to be searched is situated, or to the officer in charge of any other police station within the local limits of whose jurisdiction such place is situated, for a search warrant.","12","Investigation","Criminal Procedure",["CrPC S166 officer police station search warrant another Magistrate jurisdiction apply"]],
["169","Release of accused when evidence deficient","If, upon an investigation under this Chapter, it appears to the officer in charge of the police station that there is not sufficient evidence or reasonable ground of suspicion to justify the forwarding of the accused to a Magistrate, such officer shall, if such person is in custody, release him on his executing a bond.","12","Investigation","Criminal Procedure",["CrPC S169 release accused insufficient evidence reasonable suspicion bond custody officer police station"]],
["170","Cases to be sent to Magistrate when evidence is sufficient","If, upon an investigation under this Chapter, it appears to the officer in charge of the police station that there is sufficient evidence or reasonable ground as aforesaid, such officer shall forward the accused under custody to a Magistrate empowered to take cognizance of the offence upon a police report.","12","Investigation","Criminal Procedure",["CrPC S170 send Magistrate sufficient evidence accused custody cognizance police report forward"]],
["172","Diary of proceedings in investigation","Every police officer making an investigation under this Chapter shall day by day enter his proceedings in the investigation in a diary, setting forth the time at which the information reached him, the time at which he began and closed his investigation, the place or places visited by him, and a statement of the circumstances ascertained through his investigation.","12","Investigation","Criminal Procedure",["CrPC S172 case diary police officer investigation day time place circumstances entered diary"]],
["174","Police to inquire and report on suicide etc.","When the officer in charge of a police station or some other police officer specially empowered receives information that a person has committed suicide, or has been killed by another or by an animal, or has died under circumstances raising a reasonable suspicion that some other person has committed an offence, he shall immediately give intimation thereof to the nearest Executive Magistrate.","12","Investigation","Criminal Procedure",["CrPC S174 police inquire report suicide killed circumstances suspicion intimation Executive Magistrate inquest"]],
["175","Power to summon persons","A police officer proceeding under section 174 may, by order in writing, summon two or more persons as aforesaid for the purpose of the said investigation, and any other person who may be able to give evidence concerning the matter.","12","Investigation","Criminal Procedure",["CrPC S175 summon persons police officer writing two or more section 174 investigation evidence"]],
["176","Inquiry by Magistrate into cause of death","When any person dies while in the custody of the police or when the case is of the nature referred to in clause (i) or clause (ii) of sub-section (3) of section 174, the nearest Magistrate shall, and in any other case mentioned in sub-section (1) of section 174 any Magistrate so empowered may hold an inquiry into the cause of death.","12","Investigation","Criminal Procedure",["CrPC S176 inquiry Magistrate cause of death police custody section 174 nearest empowered hold"]],
["179","Offence triable where act is done or where consequence ensues","When an act is an offence by reason of anything which has been done and of a consequence which has ensued, the offence may be inquired into or tried by a court within the local limits of whose jurisdiction such thing has been done or such consequence has ensued.","13","Jurisdiction","Criminal Procedure",["CrPC S179 offence triable act done consequence ensued jurisdiction local limits"]],
["180","Place of trial where act is offence by reason of relation to other offence","When an act is an offence by reason of its relation to any other act which is also an offence or which would be an offence if the doer were capable of committing an offence, the first-mentioned offence may be inquired into or tried by a court within the local limits of whose jurisdiction either act was done.","13","Jurisdiction","Criminal Procedure",["CrPC S180 related offences act offence reason relation first act done jurisdiction"]],
["181","Place of trial in case of certain offences","The offences of criminal misappropriation or of criminal breach of trust may be inquired into or tried by a court within the local limits of whose jurisdiction any part of the property which is the subject of the offence was received or retained by the accused person.","13","Jurisdiction","Criminal Procedure",["CrPC S181 place trial misappropriation criminal breach trust property received retained accused jurisdiction"]],
["182","Offences committed by letters etc.","Any offence which includes cheating may, if the deception practised was by means of a letter or telecommunication message, be inquired into or tried by any court within the local limits of whose jurisdiction such letter or message was sent or was received.","13","Jurisdiction","Criminal Procedure",["CrPC S182 offence letter telecommunications cheating deception sent received jurisdiction"]],
["183","Offence committed on journey or voyage","When an offence is committed whilst the person by or against whom, or the thing in respect of which, the offence is committed is in the course of performing a journey or voyage, the offence may be inquired into or tried by a court through or into the local limits of whose jurisdiction such person or thing passed in the course of that journey.","13","Jurisdiction","Criminal Procedure",["CrPC S183 offence journey voyage person thing passed jurisdiction local limits"]],
["184","Place of trial for offences triable together","Where an offence may be inquired into or tried by more than one court and a question arises as to which of such courts shall inquire into or try that offence, it shall be decided by the High Court.","13","Jurisdiction","Criminal Procedure",["CrPC S184 place trial offences triable together more than one court High Court decide"]],
["185","Power of High Court to change venue","The High Court may, whenever it thinks fit, direct that any particular case be tried by any court competent to try the same.","13","Jurisdiction","Criminal Procedure",["CrPC S185 High Court change venue particular case court competent try"]],
["186","High Court to decide in case of doubt","Where two or more courts have taken cognizance of the same offence and a question arises as to which of them ought to inquire into or try that offence, the question shall be decided by the High Court.","13","Jurisdiction","Criminal Procedure",["CrPC S186 High Court decide doubt two courts same offence cognizance inquiry trial"]],
["187","If accused is not before magistrate having jurisdiction","If an accused person is not before the court which has taken cognizance of the case, any court may be required to compel his attendance.","13","Jurisdiction","Criminal Procedure",["CrPC S187 accused not before court cognizance compel attendance magistrate"]],
["188","Offence committed outside India","When an offence is committed outside India by a citizen of India or a person on a ship or aircraft registered in India, he may be dealt with in respect of such offence as if it had been committed at any place within India at which he may be found.","13","Jurisdiction","Criminal Procedure",["CrPC S188 offence committed outside India citizen ship aircraft registered dealt found place India"]],
["195","Prosecution for contempt of lawful authority of public servants","No court shall take cognizance of any offence punishable under sections 172 to 188 of the Indian Penal Code or of any abetment of, or attempt to commit, such offence, except on the complaint in writing of the public servant concerned or of some other public servant to whom he is subordinate.","14","Conditions for Prosecution","Criminal Procedure",["CrPC S195 prosecution contempt public servant sections 172-188 IPC complaint writing subordinate court cognizance"]],
["196","Prosecution for offences against the State","No court shall take cognizance of the offence of sedition, or any offence against the State, or any offence relating to the Army, Navy and Air Force, except with the previous sanction of the Central Government or State Government.","14","Conditions for Prosecution","Criminal Procedure",["CrPC S196 prosecution sedition offences state Army Navy Air Force sanction Central State Government previous"]],
["198","Prosecution for offences against marriage","No court shall take cognizance of an offence punishable under Chapter XX of the Indian Penal Code (relating to marriage) except upon a complaint made by some person aggrieved by the offence.","14","Conditions for Prosecution","Criminal Procedure",["CrPC S198 prosecution marriage Chapter XX IPC complaint aggrieved person court cognizance"]],
["199","Prosecution for defamation","No court shall take cognizance of an offence punishable under section 499 or section 500 of the Indian Penal Code, except upon a complaint made by some person aggrieved by the offence. However, the court of session can take cognizance upon a complaint made by the Public Prosecutor for defamation of high dignitary.","14","Conditions for Prosecution","Criminal Procedure",["CrPC S199 prosecution defamation IPC S499 S500 aggrieved person complaint court Public Prosecutor high dignitary"]],
["200","Examination of complainant","A Magistrate taking cognizance of an offence on complaint shall examine upon oath the complainant and the witnesses present, if any, and the substance of such examination shall be reduced to writing and shall be signed by the complainant and the witnesses, and also by the Magistrate.","15","Complaint","Criminal Procedure",["CrPC S200 examination complainant oath witnesses reduced writing signed Magistrate substance"]],
["202","Postponement of issue of process","Any Magistrate, on receipt of a complaint of an offence of which he is authorised to take cognizance, may, if he thinks fit, and shall, in a case where the accused is residing at a place beyond the area in which he exercises his jurisdiction, postpone the issue of process against the accused, and either inquire into the case himself or direct an investigation to be made by a police officer.","15","Complaint","Criminal Procedure",["CrPC S202 postpone process accused outside jurisdiction Magistrate inquiry police investigation direct"]],
["203","Dismissal of complaint","If, after considering the statements on oath made by the complainant and of the witnesses and the result of the inquiry or investigation, if any, under section 202, the Magistrate is of opinion that there is no sufficient ground for proceeding, he shall dismiss the complaint.","15","Complaint","Criminal Procedure",["CrPC S203 dismissal complaint no sufficient ground Magistrate opinion oath witnesses inquiry result"]],
["205","Magistrate may dispense with personal attendance","Whenever a Magistrate issues a summons, he may, if he sees reason so to do, dispense with the personal attendance of the accused and permit him to appear by his pleader.","16","Commencement of Proceedings","Criminal Procedure",["CrPC S205 dispense personal attendance accused pleader Magistrate summons permit appear"]],
["209","Commitment to Court of Session","When in a case instituted on a police report or otherwise, the accused appears or is brought before the Magistrate and it appears to the Magistrate that the offence is triable exclusively by the Court of Session, he shall commit, after complying with the provisions of section 207 or section 208, the case to the Court of Session.","17","Commitment","Criminal Procedure",["CrPC S209 commitment Court of Session Magistrate triable exclusively police report section 207 208"]],
["210","Procedure to be followed when there is a complaint case and police investigation","When in a case instituted otherwise than on a police report (hereinafter referred to as a complaint case), it is made to appear to the Magistrate, during the course of the inquiry or trial held by him, that an investigation by the police is in progress in relation to the same offence, the Magistrate shall stay the proceedings of such inquiry or trial and call for a report on the matter from the police officer.","17","Commitment","Criminal Procedure",["CrPC S210 complaint case police investigation Magistrate stay proceedings call report same offence parallel"]],
];
CRPC2.forEach(([sec,title,desc,ch,cht,cat,kw])=>add("Code of Criminal Procedure, 1973","CrPC",sec,title,desc,ch,cht,cat,...[kw]));

// ── HMA remaining sections 3-45 ──────────────────────────────────────────
const HMA2=[
["3","Definitions","In this Act: 'custom' and 'usage' signify any rule which, having been continuously and uniformly observed for a long time, has obtained the force of law among Hindus in any local area, tribe, community, group or family; 'district court' means the principal civil court of original jurisdiction in a district; 'full blood', 'half blood' and 'uterine blood' have the meanings defined in the Hindu Succession Act 1956.","1","Preliminary","Family Law",["HMA S3 definitions custom usage long time force law local area tribe community district court full blood half blood"]],
["4","Overriding effect","Save as otherwise expressly provided in this Act, any text, rule or interpretation of Hindu law or any custom or usage as part of that law in force immediately before the commencement of this Act shall cease to have effect with respect to any matter for which provision is made in this Act, and any other law in force immediately before the commencement of this Act shall cease to apply to Hindus in so far as it is inconsistent with any of the provisions contained in this Act.","1","Preliminary","Family Law",["HMA S4 overriding effect Hindu law custom usage cease other law inconsistent provisions"]],
["5","Conditions for Hindu marriage","A marriage may be solemnized between any two Hindus if: (i) neither party has a spouse living; (ii) at the time of marriage, neither party is of unsound mind or incapable of giving valid consent; (iii) the bridegroom has completed 21 years and the bride 18 years; (iv) the parties are not within the degrees of prohibited relationship; (v) the parties are not sapindas of each other.","2","Form of Marriages","Family Law",["HMA S5 conditions Hindu marriage no living spouse sound mind 21 years 18 years prohibited relationship sapinda"]],
["6","Guardianship in marriage","The guardianship of a minor in marriage is governed by section 6 of the Hindu Minority and Guardianship Act 1956. A minor's marriage requires consent of guardian.","2","Form of Marriages","Family Law",["HMA S6 guardianship marriage minor Hindu Minority Guardianship Act 1956 consent"]],
["11","Void marriages","Any marriage solemnized after commencement of this Act shall be null and void and may be declared by decree of nullity if it contravenes section 5 clause (i) (living spouse), (iv) (prohibited relationship), or (v) (sapinda relationship).","3","Void and Voidable Marriages","Family Law",["HMA S11 void marriage null void decree nullity living spouse prohibited relationship sapinda"]],
["12","Voidable marriages","A marriage solemnized shall be voidable and may be annulled by decree of nullity: if not consummated due to impotence of respondent; contravention of section 5(ii) conditions of consent; consent by force or fraud; respondent pregnant by another person at time of marriage.","3","Void and Voidable Marriages","Family Law",["HMA S12 voidable marriage annulled nullity impotence consent force fraud pregnant another person"]],
["16","Legitimacy of children of void and voidable marriages","Children of void and voidable marriages are legitimate — whether or not decree of nullity is granted.","4","Divorce","Family Law",["HMA S16 legitimacy children void voidable marriages decree nullity granted legitimate"]],
["17","Punishment of bigamy","Any marriage between two Hindus solemnized after commencement of this Act is void if either party has a husband or wife living; IPC S494 and S495 apply.","4","Divorce","Family Law",["HMA S17 bigamy void IPC S494 S495 living spouse Hindu marriage punishment"]],
["18","Punishment for contravention of certain conditions","Persons contravening section 5(iii) (age), (iv) (prohibited relationship), or (v) (sapinda) shall be punished — age: simple imprisonment 15 days or fine Rs 1,000; prohibited/sapinda: 1 month or Rs 1,000 or both.","4","Divorce","Family Law",["HMA S18 punishment contravention age 15 days fine 1000 prohibited sapinda 1 month"]],
["13","Divorce — grounds","(1) Divorce may be sought by either party on grounds: adultery; cruelty; desertion for 2 years; conversion; unsoundness of mind; leprosy (now removed); venereal disease; renouncing world; not heard alive for 7 years. (1A) After 1 year of separation: non-resumption of cohabitation after maintenance order; non-resumption after restitution decree. (2) Additional grounds for wife: husband's bigamy/pre-Act marriage with another wife living; husband guilty of rape, sodomy, bestiality; non-resumption of cohabitation after maintenance order; repudiation (option of puberty).","4","Divorce","Family Law",["HMA S13 divorce grounds adultery cruelty desertion 2 years conversion unsound mind venereal renounce 7 years bigamy rape sodomy option puberty wife additional"]],
["13B","Divorce by mutual consent","Both parties may petition for divorce by mutual consent on ground of living separately for 1 year, inability to live together, and mutual agreement. Second motion after 6 months (not later than 18 months) leads to decree of divorce. SC: period can be waived in appropriate cases under Article 142.","4","Divorce","Family Law",["HMA S13B divorce mutual consent one year separate six months eighteen months second motion Article 142 waive"]],
["13C","Divorce by wife — additional ground","A wife may also present a petition praying for divorce under section 13(2) on the ground that the husband has been guilty of rape, sodomy or bestiality since solemnization of marriage.","4","Divorce","Family Law",["HMA S13C wife petition rape sodomy bestiality husband ground"]],
["14","No petition within one year of marriage","No petition for dissolution of marriage by divorce may be presented unless at the date of presentation at least one year has elapsed since date of marriage. Exception: exceptional hardship or exceptional depravity — High Court may allow earlier petition.","4","Divorce","Family Law",["HMA S14 no petition one year marriage exception exceptional hardship depravity High Court allow earlier"]],
["21","Application of Act V of 1908","Subject to other provisions contained in this Act and to such rules as the High Court may make in this behalf, all proceedings under this Act shall be regulated, as far as may be, by the Code of Civil Procedure 1908.","5","Jurisdiction","Family Law",["HMA S21 CPC application proceedings regulated Code of Civil Procedure 1908 High Court rules"]],
["21A","Power to transfer petitions","When proceedings under this Act are pending in different courts, the Supreme Court or High Court may transfer any petition to another court.","5","Jurisdiction","Family Law",["HMA S21A transfer petition Supreme Court High Court different courts pending"]],
["21B","Special provisions relating to trial and disposal of petitions","The trial of a petition shall, as far as possible, be continued from day to day until its conclusion, and the petition shall be tried as expeditiously as possible.","5","Jurisdiction","Family Law",["HMA S21B trial day to day expeditiously conclusion petition disposal"]],
["21C","Documentary evidence","Notwithstanding anything in any enactment to the contrary, no document shall be inadmissible in evidence in any proceeding at the trial of a petition under this Act on the ground that it is not duly stamped or registered.","5","Jurisdiction","Family Law",["HMA S21C documentary evidence not inadmissible unstamped unregistered proceeding trial"]],
["22","Proceedings to be in camera and may not be printed or published","Every proceeding under this Act shall be conducted in camera if either party so desires or if the court so thinks fit, and it shall not be lawful for any person to print or publish any matter in relation to any such proceeding except a judgment of the High Court or the Supreme Court.","5","Jurisdiction","Family Law",["HMA S22 in camera proceedings print publish prohibited High Court Supreme Court judgment exception"]],
["23","Decree in proceedings","In any proceeding under this Act, the court shall not pass a decree unless it is satisfied that the petitioner has not in any manner been taking advantage of his or her own wrong or disability for the purpose of obtaining a relief; there has been no collusion; there has not been any unnecessary or improper delay.","5","Jurisdiction","Family Law",["HMA S23 decree proceeding not own wrong collusion unnecessary delay court satisfied relief"]],
["24","Maintenance pendente lite and expenses","Where in any proceeding under this Act it appears that either the wife or husband has no independent income sufficient for support and expenses, the court may order the respondent to pay monthly during the proceeding such sum as the court thinks reasonable.","5","Jurisdiction","Family Law",["HMA S24 maintenance pendente lite expenses proceeding monthly reasonable wife husband independent income court"]],
["28A","Enforcement of decrees and orders","All decrees and orders made by the court in any proceeding under this Act shall be enforced in the like manner as the decrees and orders of the court made in the exercise of its original civil jurisdiction are enforced.","5","Jurisdiction","Family Law",["HMA S28A enforcement decrees orders like manner original civil jurisdiction court proceeding"]],
];
HMA2.forEach(([sec,title,desc,ch,cht,cat,kw])=>add("Hindu Marriage Act, 1955","HMA",sec,title,desc,ch,cht,cat,...[kw]));

